// Workflow D · Stage D-4 — provider callback receiver (VoiceBip voice/SMS, Meta WhatsApp).
// One authenticated webhook for every asynchronous provider event: delivery reports,
// call outcomes and recordings. Django remains the source of truth: this node only
// normalizes the provider's vocabulary, then POSTs to /interactions/ where the
// status-rank guard decides whether the stored row may advance.
//
// Phase 1: Meta WhatsApp is understood natively. Meta wraps statuses inside
// entry[].changes[].value.statuses[] and can batch several of them into ONE request
// (sent + delivered arrive together when the phone is online). Every status becomes
// its own item, so the tail of a batch is never silently dropped.
const src = $input.first().json || {};
const body = src.body || {};
const query = src.query || {};
const headers = src.headers || {};

const env = function (name, fallback) {
  try {
    var v = $env[name];
    return (v === undefined || v === null) ? (fallback || '') : String(v);
  } catch (e) { return fallback || ''; }
};
const first = function () {
  for (var i = 0; i < arguments.length; i++) {
    var v = arguments[i];
    if (v !== undefined && v !== null && String(v).trim() !== '') return v;
  }
  return '';
};
const norm = function (v) {
  return String(v || '').trim().toLowerCase().replace(new RegExp('[^a-z0-9]+', 'g'), '_');
};

// ---------- 1. Authentication (fail closed) ----------
const expected = env('PROVIDER_CALLBACK_TOKEN');
const provided = String(first(
  query.token,
  query.access_token,
  headers['x-provider-token'],
  headers['x-callback-token'],
  headers['x-webhook-token'],
  body.token
)).trim();
const authorized = Boolean(expected) && provided === expected;

if (!authorized) {
  return [{ json: {
    authorized: false,
    skip: true,
    reason: expected ? 'bad_token' : 'callback_token_not_configured',
    http_code: 401,
    response: {
      ok: false,
      error: 'unauthorized',
      reason: expected ? 'invalid_callback_token' : 'receiver_not_configured',
    },
  } }];
}

// ---------- 2. Unwrap the provider envelope ----------
// VoiceBip posts one flat event. Meta posts a batch. Both become a list of raw
// event objects; each is normalized into one item below.
const unwrap = function (b) {
  const entries = Array.isArray(b.entry) ? b.entry : null;
  if (!entries) return [{ meta: false, event: b }];

  const out = [];
  for (var i = 0; i < entries.length; i++) {
    const changes = Array.isArray(entries[i] && entries[i].changes) ? entries[i].changes : [];
    for (var c = 0; c < changes.length; c++) {
      const value = (changes[c] && changes[c].value) || {};
      const statuses = Array.isArray(value.statuses) ? value.statuses : [];
      for (var s = 0; s < statuses.length; s++) {
        const st = statuses[s] || {};
        out.push({
          meta: true,
          event: {
            status: st.status,
            id: st.id,
            recipient_id: st.recipient_id,
            timestamp: st.timestamp,
            biz_opaque_callback_data: st.biz_opaque_callback_data,
            errors: st.errors,
            conversation: st.conversation,
            pricing: st.pricing,
          },
        });
      }
      // Inbound patient replies share this webhook in Meta's model. They are
      // Workflow C's job (Telegram is the launch channel), so they are acked and
      // ignored here rather than mis-recorded as an outbound SMS.
      const msgs = Array.isArray(value.messages) ? value.messages : [];
      if (msgs.length && !statuses.length) {
        out.push({ meta: true, inbound: true, event: { id: msgs[0].id } });
      }
    }
  }
  return out;
};

// ---------- 3. Provider vocabulary -> clinic vocabulary ----------
// Adjust these two tables (only these) when VoiceBip's real payload spec lands.
const STATUS_ALIASES = {
  queued: 'queued', pending: 'queued', scheduled: 'queued', initiated: 'queued', created: 'queued',
  sent: 'sent', submitted: 'sent', accepted: 'sent', ringing: 'sent', in_progress: 'sent', calling: 'sent',
  delivered: 'delivered', delivery: 'delivered', read: 'delivered', delivery_success: 'delivered', message_delivered: 'delivered',
  answered: 'answered', completed: 'answered', call_answered: 'answered', call_completed: 'answered', human_answered: 'answered',
  no_answer: 'no_answer', noanswer: 'no_answer', unanswered: 'no_answer', busy: 'no_answer',
  line_busy: 'no_answer', voicemail: 'no_answer', machine_detected: 'no_answer', no_response: 'no_answer',
  failed: 'failed', failure: 'failed', error: 'failed', rejected: 'failed', undelivered: 'failed',
  delivery_failed: 'failed', cancelled: 'failed', canceled: 'failed', call_failed: 'failed',
  expired: 'expired', timeout: 'expired', timed_out: 'expired', offer_expired: 'expired',
};
const CHANNEL_ALIASES = {
  voice: 'voice', call: 'voice', voice_call: 'voice', voicecall: 'voice', phone: 'voice', ivr: 'voice',
  sms: 'sms', text: 'sms', message: 'sms', messaging: 'sms', text_message: 'sms',
  whatsapp: 'whatsapp', wa: 'whatsapp', whatsapp_cloud: 'whatsapp', whatsapp_message: 'whatsapp',
  telegram: 'telegram', tg: 'telegram',
};

const STATUS_LABEL = {
  queued: 'queued', sent: 'sent', delivered: 'delivered',
  answered: 'answered', no_answer: 'did not answer', failed: 'failed', expired: 'expired',
};

// Meta nests the failure reason: errors[0].error_data.details holds the human
// sentence, title is the short label, code is the numeric reason (e.g. 131047).
const metaError = function (errors) {
  if (!Array.isArray(errors) || !errors.length) return '';
  const e0 = errors[0] || {};
  const detail = String(first(
    e0.error_data && e0.error_data.details,
    e0.title,
    e0.message,
    'WhatsApp delivery failed'
  ));
  return e0.code ? '(' + e0.code + ') ' + detail : detail;
};

const normalize = function (wrapped) {
  const ev = wrapped.event || {};
  const isMeta = wrapped.meta === true;

  const rawEvent = String(first(ev.event, ev.type, ev.status, ev.call_status, ev.delivery_status, ev.state));
  const eventTail = norm(rawEvent).split('_').pop() || '';
  const rawStatus = norm(first(ev.status, ev.call_status, ev.delivery_status, ev.state, rawEvent));
  const status = STATUS_ALIASES[rawStatus] || STATUS_ALIASES[eventTail] || STATUS_ALIASES[norm(rawEvent)] || '';

  const externalRef = String(first(
    ev.id, ev.external_ref, ev.externalRef, ev.message_id, ev.messageId,
    ev.call_id, ev.callId, ev.reference, ev.sid, ev.provider_ref
  ));

  // Meta echoes biz_opaque_callback_data (set by the dispatcher on every send),
  // which is how a real wamid is linked back to a BookingRequest.
  let requestCode = String(first(
    ev.biz_opaque_callback_data,
    ev.request_code,
    ev.client_reference,
    ev.metadata && ev.metadata.request_code,
    ev.custom_data && ev.custom_data.request_code
  ));
  if (!requestCode) {
    const hit = externalRef.match(new RegExp('REQ-[0-9]{4}-[0-9]+', 'i'));
    if (hit) requestCode = hit[0].toUpperCase();
  }

  let channel = CHANNEL_ALIASES[norm(first(ev.channel, ev.medium, ev.channel_type))] || '';
  if (!channel) {
    const ref = externalRef.toLowerCase();
    if (ref.indexOf('voice') !== -1 || ref.indexOf('call') !== -1) channel = 'voice';
    else if (ref.indexOf('sms') !== -1) channel = 'sms';
    else if (ref.indexOf('whatsapp') !== -1 || ref.indexOf('wa-') !== -1) channel = 'whatsapp';
  }
  if (!channel && (status === 'answered' || status === 'no_answer')) channel = 'voice';
  if (!channel && rawEvent) {
    const evn = norm(rawEvent);
    if (evn.indexOf('sms') === 0) channel = 'sms';
    else if (evn.indexOf('whatsapp') === 0 || evn.indexOf('wa_') === 0) channel = 'whatsapp';
    else if (evn.indexOf('call') === 0 || evn.indexOf('voice') === 0) channel = 'voice';
  }
  // A Meta status event is WhatsApp by construction, whatever the ref looks like.
  if (isMeta) channel = 'whatsapp';
  // Last resort: VoiceBip's remaining product is SMS. Confirm with the partner contract.
  if (!channel) channel = 'sms';

  const explicitProvider = norm(first(ev.provider, ev.provider_name, ev.vendor));
  let provider = '';
  if (explicitProvider.indexOf('voicebip') !== -1 || explicitProvider.indexOf('bip') !== -1) provider = 'voicebip';
  else if (explicitProvider.indexOf('meta') !== -1 || explicitProvider.indexOf('whatsapp') !== -1) provider = 'meta_whatsapp';
  else if (explicitProvider.indexOf('telegram') !== -1) provider = 'telegram';
  if (!provider) provider = (isMeta || channel === 'whatsapp') ? 'meta_whatsapp' : (channel === 'telegram' ? 'telegram' : 'voicebip');

  const phone = String(first(
    ev.patient_phone, ev.recipient_id, ev.to, ev.phone, ev.destination, ev.recipient, ev.customer_number,
    ev.metadata && ev.metadata.patient_phone,
    ev.metadata && ev.metadata.to
  ));

  const patientName = String(first(
    ev.patient_name, ev.customer_name,
    ev.metadata && ev.metadata.patient_name,
    ev.contacts && ev.contacts[0] && ev.contacts[0].profile && ev.contacts[0].profile.name
  ));

  const rawDuration = first(ev.call_duration_seconds, ev.duration_seconds, ev.duration, ev.call_duration, ev.billable_duration);
  const duration = (rawDuration === '' || isNaN(Number(rawDuration))) ? null : Math.max(0, Math.round(Number(rawDuration)));
  const recording = String(first(ev.recording_url, ev.recordingUrl, ev.recording && ev.recording.url, ev.call_recording_url));
  const transcript = String(first(ev.transcript, ev.transcription, ev.call_transcript));

  let errorDetail = '';
  if (isMeta) {
    errorDetail = metaError(ev.errors);
  } else {
    const rawError = first(ev.error_detail, ev.error, ev.reason, ev.failure_reason, ev.error_message);
    errorDetail = (rawError && typeof rawError === 'object') ? JSON.stringify(rawError) : String(rawError || '');
  }

  const summary = String(first(ev.summary, ev.note, 'Provider callback: ' + channel + ' ' + (STATUS_LABEL[status] || status)));

  return {
    isMeta: isMeta,
    inbound: wrapped.inbound === true,
    status: status,
    channel: channel,
    provider: provider,
    externalRef: externalRef,
    patient_name: patientName,
    requestCode: requestCode,
    phone: phone,
    duration: duration,
    recording: recording,
    transcript: transcript,
    errorDetail: errorDetail,
    summary: summary,
  };
};

// ---------- 4. Ignore anything we cannot place (still a 200, so the provider stops retrying) ----------
const ignoreItem = function (reason, extra) {
  return { json: Object.assign({
    authorized: true, skip: true, reason: reason, http_code: 200,
    response: { ok: true, ignored: true, reason: reason, external_ref: (extra && extra.external_ref) || null },
  }, extra || {}) };
};

const items = [];
const events = unwrap(body);
for (var e = 0; e < events.length; e++) {
  const wrapped = events[e];
  if (wrapped.inbound) {
    items.push(ignoreItem('inbound_message_not_a_status_event', {
      external_ref: String(wrapped.event.id || ''),
    }));
    continue;
  }

  const n = normalize(wrapped);
  if (!n.status) { items.push(ignoreItem('unknown_status', { external_ref: n.externalRef })); continue; }
  if (!n.externalRef) { items.push(ignoreItem('missing_external_ref')); continue; }

  // ---------- 5. Ready to hand to Django ----------
  const payload = {
    provider: n.provider,
    channel: n.channel,
    direction: 'outbound',
    status: n.status,
    patient_name: n.patientName,
    patient_phone: n.phone,
    request_code: n.requestCode,
    external_ref: n.externalRef,
    summary: n.summary,
    error_detail: n.errorDetail,
  };
  if (n.duration !== null) payload.call_duration_seconds = n.duration;
  if (n.recording) payload.recording_url = n.recording;
  if (n.transcript) payload.transcript = n.transcript;

  items.push({ json: {
    authorized: true,
    skip: false,
    reason: null,
    http_code: 200,
    payload: payload,
    response: { ok: true, accepted: true, external_ref: n.externalRef, status: n.status, channel: n.channel },
  } });
}

if (!items.length) items.push(ignoreItem('empty_callback'));
return items;

// Workflow D · Stage D-4 — classify a failed /interactions/ write.
// A 4xx means Django will never accept this event (bad vocabulary, unknown request_code,
// invalid recording URL): retrying cannot fix it, so answer 200 and let the workflow log
// stand. A 5xx / timeout / connection refusal is transient: answer 500 so the provider
// retries the delivery report.
const incoming = $input.first().json || {};
const raw = String((incoming.error && incoming.error.message) || incoming.error || '');
const hit = raw.match(new RegExp('(^|[^0-9])([45][0-9][0-9])([^0-9]|$)'));
const code = hit ? Number(hit[2]) : 0;
const clientError = code >= 400 && code < 500;

return [{ json: {
  http_code: clientError ? 200 : 500,
  accepted: false,
  rejected: clientError,
  retry: !clientError,
  reason: clientError ? 'django_rejected_event' : 'django_unavailable',
  detail: raw.slice(0, 300),
} }];

// Phase 1 — Meta webhook verification.
// Meta registers a callback URL by calling
//   GET <url>?hub.mode=subscribe&hub.challenge=<nonce>&hub.verify_token=<token>
// and expects the challenge echoed back as plain text. Without this the callback
// URL cannot be added in the Meta console at all, so the WhatsApp leg could never
// go live even with every credential filled in.
// Fail closed: an unset WHATSAPP_VERIFY_TOKEN answers 403, never a challenge.
const src = $input.first().json || {};
const q = src.query || {};
const env = (name) => {
  try { const v = $env[name]; return (v === undefined || v === null) ? '' : String(v); }
  catch (e) { return ''; }
};

const mode = String(q['hub.mode'] || '').trim().toLowerCase();
if (mode !== 'subscribe') {
  // Not a verification request: continue into the normal callback pipeline.
  return [{ json: Object.assign({ handshake: false }, src) }];
}

const expected = env('WHATSAPP_VERIFY_TOKEN').trim();
const provided = String(q['hub.verify_token'] || '').trim();
const challenge = String(q['hub.challenge'] || '');

if (!expected) {
  return [{ json: { handshake: true, handshake_code: 403, challenge: '', reason: 'verify_token_not_configured' } }];
}
if (provided !== expected) {
  return [{ json: { handshake: true, handshake_code: 403, challenge: '', reason: 'bad_verify_token' } }];
}
return [{ json: { handshake: true, handshake_code: 200, challenge: challenge, reason: null } }];
